SELECT CAST(COUNT(CASE WHEN p.dischtime - p.admittime >= 7 THEN 1 END) AS FLOAT) / NULLIF(COUNT(*), 0) AS proportion_with_long_stay, PERCENT_RANK() OVER (ORDER BY (p.dischtime - p.admittime)) AS percentile_rank FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 85 AND 90 AND a.discharge_location IN ('home', 'facility') AND p.dod IS NOT NULL;